    <aside className={cn('fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col bg-[#16243b] text-slate-300 transition-transform duration-300 lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}><div className="flex h-20 items-center border-b border-white/10 px-6"><div className="mr-3 flex h-9 w-9 items-center justify-center rounded-xl bg-teal-400 text-slate-950"><Target className="h-5 w-5" /></div><div><div className="font-display text-sm font-bold text-white">Local Visibility</div><div className="text-[10px] font-semibold uppercase tracking-widest text-teal-300">PRO</div></div><button className="ml-auto text-slate-400 lg:hidden" onClick={() => setOpen(false)}><X className="h-5 w-5" /></button></div>
      <div className="border-b border-white/10 px-4 py-4"><div className="rounded-xl bg-white/[0.07] p-3"><div className="flex items-center gap-2"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-teal-400/20 text-teal-300"><BriefcaseBusiness className="h-4 w-4" /></div><div className="min-w-0"><p className="truncate text-xs font-semibold text-white">Bridge Legal Services</p><p className="flex items-center gap-1 text-[11px] text-slate-400"><MapPin className="h-3 w-3" /> Toronto, Ontario</p></div><ChevronRight className="ml-auto h-4 w-4 text-slate-500" /></div></div></div>
      <nav className="flex-1 overflow-y-auto px-3 py-4"><p className="mb-2 px-3 text-[10px] font-bold uppercase tracking-[0.18em] text-slate-500">Workspace</p>{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} className={cn('mb-1 flex items-center gap-3 rounded-lg px-3 py-2.5 text-[13px] font-medium transition-colors', location === href ? 'bg-teal-400 text-slate-950 shadow-sm' : 'text-slate-400 hover:bg-white/[0.07] hover:text-white')}><Icon className="h-[16px] w-[16px]" />{label}{label === 'Reviews' && <span className="ml-auto rounded-full bg-amber-300 px-1.5 text-[10px] font-bold text-slate-900">5</span>}</Link>)}<p className="mb-2 mt-7 px-3 text-[10px] font-bold uppercase tracking-[0.18em] text-slate-500">Account</p>{supportNav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} className={cn('mb-1 flex items-center gap-3 rounded-lg px-3 py-2.5 text-[13px] font-medium transition-colors', location === href ? 'bg-teal-400 text-slate-950' : 'text-slate-400 hover:bg-white/[0.07] hover:text-white')}><Icon className="h-[16px] w-[16px]" />{label}</Link>)}</nav>
      <div className="border-t border-white/10 p-4"><div className="flex items-center gap-3 rounded-xl bg-white/[0.07] p-3"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-amber-200 text-xs font-bold text-slate-800">AM</div><div className="min-w-0"><p className="text-xs font-semibold text-white">Ahmad Malik</p><p className="truncate text-[11px] text-slate-500">Client account</p></div><MoreHorizontal className="ml-auto h-4 w-4 text-slate-500" /></div></div>
    </aside>
    {open && <button aria-label="Close menu" className="fixed inset-0 z-30 bg-slate-950/30 lg:hidden" onClick={() => setOpen(false)} />}
    <main className="lg:pl-[248px]"><header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b border-slate-200/80 bg-[#f3f6fa]/90 px-5 backdrop-blur-md sm:px-8"><div className="flex items-center gap-3"><button className="rounded-lg p-2 text-slate-600 hover:bg-white lg:hidden" onClick={() => setOpen(true)}><Menu className="h-5 w-5" /></button><div className="hidden items-center gap-2 text-xs text-slate-400 sm:flex"><span>Bridge Legal Services</span><ChevronRight className="h-3 w-3" /><span className="font-medium text-slate-700">{nav.find((item) => item.href === location)?.label ?? supportNav.find((item) => item.href === location)?.label ?? 'Overview'}</span></div></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-full bg-white px-3 py-1.5 text-[11px] font-medium text-slate-500 shadow-sm sm:flex"><span className={cn('h-1.5 w-1.5 rounded-full', health.isError ? 'bg-rose-500' : 'bg-teal-500')} /> Demo data workspace</div><button className="relative rounded-lg p-2 text-slate-500 hover:bg-white"><Bell className="h-[18px] w-[18px]" /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-amber-400" /></button><div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-800 text-[11px] font-bold text-white">AM</div></div></header><div className="mx-auto max-w-[1440px] px-5 py-7 sm:px-8 lg:px-10">{children}</div></main>
