function MiniChart({ values, color = '#20ad9f', height = 170 }: { values: number[]; color?: string; height?: number }) {
  const max = Math.max(...values), min = Math.min(...values), range = max - min || 1; const points = values.map((v, i) => `${(i / (values.length - 1)) * 100},${height - 18 - ((v - min) / range) * (height - 42)}`).join(' ');
  return <svg viewBox={`0 0 100 ${height}`} preserveAspectRatio="none" className="h-full w-full"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={color} stopOpacity=".22" /><stop offset="1" stopColor={color} stopOpacity="0" /></linearGradient></defs><path d={`M ${points} L 100,${height} L 0,${height} Z`} fill="url(#chartFill)" /><polyline points={points} fill="none" stroke={color} strokeWidth="1.7" vectorEffect="non-scaling-stroke" />{values.map((v, i) => <circle key={i} cx={`${(i / (values.length - 1)) * 100}`} cy={height - 18 - ((v - min) / range) * (height - 42)} r="1.6" fill="white" stroke={color} strokeWidth="1" vectorEffect="non-scaling-stroke" />)}</svg>;
}
function Progress({ label, value }: { label: string; value: number }) { return <div className="mb-4 last:mb-0"><div className="mb-1.5 flex justify-between text-xs"><span className="font-medium text-slate-600">{label}</span><span className="font-bold text-slate-800">{value}%</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-teal-500 transition-all duration-700" style={{ width: `${value}%` }} /></div></div>; }

function Overview() {
  const q = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey(), staleTime: 60_000 } }); const d = q.data;
  const fallback = { business: { name: 'Bridge Legal Services', location: 'Toronto, Ontario', category: 'Traffic Ticket Defence / Paralegal' }, visibilityScore: 87, visibilityChange: 6.4, rating: 4.9, reviewCount: 76, listingHealthy: 46, listingTotal: 50, keywordsImproving: 12, trend: [{ month: 'Mar', score: 71 }, { month: 'Apr', score: 74 }, { month: 'May', score: 78 }, { month: 'Jun', score: 81 }, { month: 'Jul', score: 84 }, { month: 'Aug', score: 87 }], profileHealth: [{ label: 'Google Business Profile', value: 92 }, { label: 'Citations', value: 92 }, { label: 'Reviews', value: 95 }, { label: 'Keyword Visibility', value: 78 }, { label: 'Competitor Position', value: 81 }], recentReviews: [], recommendations: [], tasks: [] };
  const data = d ?? fallback; const reviews = data.recentReviews ?? []; const tasks = data.tasks ?? []; const recs = data.recommendations ?? [];
  return <><PageHeader eyebrow="Overview" title="Good morning, Ahmad" detail={`${data.business.name} · ${data.business.location}`} action={<select className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 outline-none"><option>This month</option><option>Last 90 days</option></select>} /><QueryState loading={q.isLoading} error={q.error}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Local visibility" value={`${data.visibilityScore}/100`} detail={`+${data.visibilityChange}% vs last month`} icon={TrendingUp} trend="up" /><Metric label="Google rating" value={data.rating.toFixed(1)} detail={`${data.reviewCount} reviews · +7 this month`} icon={Star} accent="amber" /><Metric label="Listings" value={`${data.listingHealthy}/${data.listingTotal}`} detail={`${Math.round(data.listingHealthy / data.listingTotal * 100)}% healthy`} icon={Globe2} /><Metric label="Keywords" value={`${data.keywordsImproving}`} detail="Improving this month" icon={BarChart3} accent="navy" trend="up" /></div>
      <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]"><Card><SectionTitle title="Local visibility score" detail="Your search presence over the last six months" action={<Badge tone="teal">+16 points</Badge>} /><div className="mb-4 flex items-baseline gap-2"><span className="font-display text-3xl font-bold text-slate-900">{data.visibilityScore}</span><span className="text-sm text-slate-400">/ 100</span></div><div className="h-[205px]"><MiniChart values={data.trend.map((x) => x.score)} /></div><div className="mt-2 flex justify-between text-[11px] text-slate-400">{data.trend.map((x) => <span key={x.month}>{x.month}</span>)}</div></Card><Card><SectionTitle title="Profile health" detail="A complete profile earns more trust" action={<Link href="/google-profile" className="text-xs font-semibold text-teal-700 hover:text-teal-800">Full audit <ChevronRight className="inline h-3 w-3" /></Link>} />{data.profileHealth.map((m) => <Progress key={m.label} {...m} />)}</Card></div>
      <div className="mt-5 grid gap-5 xl:grid-cols-[1.15fr_1fr_1fr]"><Card><SectionTitle title="Listing health" action={<Link href="/listings" className="text-xs font-semibold text-teal-700">View all</Link>} /><div className="mb-5 flex items-end gap-2"><span className="font-display text-3xl font-bold">{data.listingHealthy}</span><span className="mb-1 text-sm text-slate-400">/ {data.listingTotal} healthy</span></div><div className="h-2 rounded-full bg-slate-100"><div className="h-full rounded-full bg-teal-500" style={{ width: `${data.listingHealthy / data.listingTotal * 100}%` }} /></div><div className="mt-5 grid grid-cols-3 gap-2 text-center text-xs"><div><p className="font-bold text-teal-700">46</p><p className="mt-1 text-slate-400">Healthy</p></div><div><p className="font-bold text-amber-600">3</p><p className="mt-1 text-slate-400">Attention</p></div><div><p className="font-bold text-slate-600">1</p><p className="mt-1 text-slate-400">Pending</p></div></div></Card><Card><SectionTitle title="Your reputation" action={<Link href="/reviews" className="text-xs font-semibold text-teal-700">Inbox</Link>} /><div className="mb-4 flex items-center gap-3"><span className="font-display text-3xl font-bold">{data.rating.toFixed(1)}</span><div><div className="flex text-amber-400"><Star className="h-4 w-4 fill-current" /><Star className="h-4 w-4 fill-current" /><Star className="h-4 w-4 fill-current" /><Star className="h-4 w-4 fill-current" /><Star className="h-4 w-4 fill-current" /></div><p className="mt-1 text-xs text-slate-500">{data.reviewCount} Google reviews</p></div></div>{reviews.slice(0, 2).map((r) => <div key={r.id} className="border-t border-slate-100 py-3"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-slate-700">{r.customer}</p><span className="text-[10px] text-slate-400">{fmtDate(r.date)}</span></div><p className="mt-1 line-clamp-1 text-xs text-slate-500">{r.text}</p></div>)}{!reviews.length && <p className="border-t border-slate-100 pt-4 text-xs text-slate-500">Recent review activity will appear here.</p>}</Card><Card><SectionTitle title="Needs your attention" action={<Link href="/tasks" className="text-xs font-semibold text-teal-700">All tasks</Link>} />{tasks.slice(0, 3).map((task) => <div key={task.id} className="mb-3 flex items-center gap-3 last:mb-0"><div className={cn('h-2 w-2 rounded-full', task.priority === 'high' ? 'bg-rose-500' : task.priority === 'medium' ? 'bg-amber-400' : 'bg-teal-500')} /><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-slate-700">{task.title}</p><p className="mt-0.5 text-[11px] text-slate-400">Due {fmtDate(task.dueDate)}</p></div><Badge tone={task.status === 'completed' ? 'teal' : task.priority === 'high' ? 'rose' : 'amber'}>{task.status === 'completed' ? 'Done' : task.priority}</Badge></div>)}{!tasks.length && <p className="text-xs text-slate-500">Your task queue is clear.</p>}</Card></div>
      <Card className="mt-5"><SectionTitle title="AI recommendations" detail="The clearest opportunities in your account" action={<Link href="/recommendations" className="text-xs font-semibold text-teal-700">Open assistant</Link>} /><div className="grid gap-3 md:grid-cols-3">{(recs.length ? recs : [{ id: 1, priority: 'high', title: 'Increase review volume', description: 'Competitors are winning on review volume.', action: 'Request reviews from recent customers.', impact: 'High impact' }, { id: 2, priority: 'medium', title: 'Resolve citation mismatch', description: 'One directory has an address mismatch.', action: 'Review your BBB listing details.', impact: 'Medium impact' }, { id: 3, priority: 'medium', title: 'Strengthen service content', description: 'A local service page can support ranking growth.', action: 'Expand the stunt driving page.', impact: 'Medium impact' }]).slice(0, 3).map((r) => <div key={r.id} className="rounded-xl border border-slate-200 p-4"><div className="flex items-center justify-between"><Badge tone={r.priority === 'high' ? 'rose' : 'amber'}>{r.priority} priority</Badge><Sparkles className="h-4 w-4 text-teal-500" /></div><h3 className="mt-3 text-sm font-bold text-slate-800">{r.title}</h3><p className="mt-1 text-xs leading-5 text-slate-500">{r.description}</p><p className="mt-3 text-xs font-semibold text-slate-700">{r.action}</p></div>)}</div></Card>
    </QueryState></>;
}

function Listings() {
  const q = useGetListings({ query: { queryKey: getGetListingsQueryKey() } }); const [filter, setFilter] = useState('all'); const [selected, setSelected] = useState<number | null>(null); const rows = q.data ?? []; const filtered = rows.filter((x) => filter === 'all' || x.status === filter);
  return <><PageHeader eyebrow="Citations" title="Business listings" detail="Monitor your business information across major platforms." action={<Button><Plus className="h-4 w-4" /> Add listing</Button>} /><QueryState loading={q.isLoading} error={q.error}><Card><div className="mb-5 flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><span className="font-display text-2xl font-bold text-slate-900">46 <span className="text-base font-medium text-slate-400">/ 50 healthy</span></span><p className="mt-1 text-xs text-slate-500">Last scan completed today at 06:12</p></div><div className="flex gap-1 rounded-lg bg-slate-100 p-1">{['all', 'healthy', 'attention', 'pending'].map((x) => <button key={x} onClick={() => setFilter(x)} className={cn('rounded-md px-3 py-1.5 text-xs font-semibold capitalize', filter === x ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500')}>{x === 'all' ? 'All listings' : x}</button>)}</div></div>{!filtered.length ? <EmptyState title="No listings in this view" detail="Try another status filter or add a directory to monitor." icon={Globe2} /> : <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="border-y border-slate-100 text-[10px] uppercase tracking-widest text-slate-400"><tr><th className="py-3 font-bold">Directory</th><th>Status</th><th>Name</th><th>Address</th><th>Phone</th><th>Website</th><th>Last checked</th><th /></tr></thead><tbody>{filtered.map((x) => <tr key={x.id} className="border-b border-slate-100 last:border-0"><td className="py-4 font-semibold text-slate-800">{x.directory}</td><td><Badge tone={x.status === 'healthy' ? 'teal' : x.status === 'attention' ? 'amber' : 'slate'}>{x.status}</Badge></td>{[x.nameMatch, x.addressMatch, x.phoneMatch, x.websiteMatch].map((match, i) => <td key={i}><span className={match ? 'text-teal-600' : 'text-rose-600'}>{match ? <Check className="h-4 w-4" /> : <X className="h-4 w-4" />}</span></td>)}<td className="text-xs text-slate-500">{fmtDate(x.lastChecked)}</td><td><Button variant="ghost" onClick={() => setSelected(x.id)}>Details</Button></td></tr>)}</tbody></table></div>}</Card>{selected && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4" onClick={() => setSelected(null)}><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-teal-700">Listing audit</p><h2 className="mt-1 font-display text-xl font-bold">{rows.find((x) => x.id === selected)?.directory}</h2></div><button onClick={() => setSelected(null)}><X className="h-5 w-5 text-slate-400" /></button></div><p className="mt-5 rounded-xl bg-amber-50 p-4 text-sm text-amber-800">{rows.find((x) => x.id === selected)?.issue ?? 'This listing is matching your core business information.'}</p><Button className="mt-5 w-full" onClick={() => setSelected(null)}>Close details</Button></div></div>}</QueryState></>;
}

function Reviews() {
  const q = useGetReviews({ query: { queryKey: getGetReviewsQueryKey() } }); const respond = useRespondToReview(); const [rating, setRating] = useState('all'); const [active, setActive] = useState<any>(null); const [response, setResponse] = useState('');
  const rows = (q.data ?? []).filter((r) => rating === 'all' || r.rating === Number(rating)); const openResponse = (review: any) => { setActive(review); setResponse(`Thank you for sharing your experience, ${review.customer}. We’re glad our team could support you. Your trust means a great deal to Bridge Legal Services.`); };
  return <><PageHeader eyebrow="Reputation" title="Review inbox" detail="Keep every customer conversation visible and thoughtfully answered." action={<div className="flex items-center gap-2"><Badge tone="amber">5 need response</Badge><Button variant="secondary"><Bell className="h-4 w-4" /> Review alerts</Button></div>} /><QueryState loading={q.isLoading} error={q.error}><div className="mb-5 grid gap-4 sm:grid-cols-3"><Metric label="Total reviews" value={`${q.data?.length ?? 136}`} detail="Across monitored sources" icon={MessageSquare} /><Metric label="Average rating" value="4.8" detail="Strong customer sentiment" icon={Star} accent="amber" /><Metric label="This month" value="+7" detail="New reviews received" icon={TrendingUp} trend="up" /></div><Card><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="flex gap-1 rounded-lg bg-slate-100 p-1">{['all', '5', '4', '3', '2', '1'].map((x) => <button key={x} onClick={() => setRating(x)} className={cn('rounded-md px-3 py-1.5 text-xs font-semibold', rating === x ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500')}>{x === 'all' ? 'All' : `${x} star`}</button>)}</div><select className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-xs font-medium"><option>Newest first</option><option>Needs response</option></select></div>{!rows.length ? <EmptyState title="No reviews yet" detail="New reviews will land here as they are monitored." icon={MessageSquare} /> : <div className="space-y-3">{rows.map((r) => <div key={r.id} className="rounded-xl border border-slate-200 p-4 transition-colors hover:border-slate-300"><div className="flex flex-col gap-3 sm:flex-row sm:items-start"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-slate-100 text-xs font-bold text-slate-600">{initials(r.customer)}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-sm font-bold text-slate-800">{r.customer}</span><span className="flex text-amber-400">{Array.from({ length: 5 }).map((_, i) => <Star key={i} className={cn('h-3.5 w-3.5', i < r.rating ? 'fill-current' : 'text-slate-200')} />)}</span><Badge tone="slate">{r.platform}</Badge><span className="text-xs text-slate-400">{fmtDate(r.date)}</span></div><p className="mt-3 text-sm leading-6 text-slate-600">{r.text}</p></div><div className="flex shrink-0 gap-2">{r.responded ? <Badge tone="teal"><Check className="mr-1 h-3 w-3" /> Responded</Badge> : <Button variant="secondary" onClick={() => openResponse(r)}><Sparkles className="h-3.5 w-3.5 text-teal-600" /> Draft response</Button>}</div></div></div>)}</div>}</Card>{active && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4" onClick={() => setActive(null)}><div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-teal-700">Demo response flow</p><h2 className="mt-1 font-display text-xl font-bold text-slate-900">Suggested response</h2></div><button onClick={() => setActive(null)}><X className="h-5 w-5 text-slate-400" /></button></div><p className="mt-4 rounded-xl bg-slate-50 p-4 text-xs leading-5 text-slate-500">This is a draft only. Nothing will be published to Google or Yelp.</p><textarea value={response} onChange={(e) => setResponse(e.target.value)} rows={5} className="mt-4 w-full resize-none rounded-xl border border-slate-300 p-3 text-sm outline-none ring-teal-500 focus:ring-2" /><div className="mt-5 flex justify-end gap-2"><Button variant="secondary" onClick={() => setActive(null)}>Cancel</Button><Button disabled={respond.isPending || !response.trim()} onClick={() => respond.mutate({ id: active.id, data: { response } }, { onSuccess: () => setActive(null) })}>{respond.isPending ? 'Saving…' : 'Approve draft'}</Button></div></div></div>}</QueryState></>;
}

function Rankings() { const q = useGetRankings({ query: { queryKey: getGetRankingsQueryKey() } }); const rows = q.data ?? []; return <><PageHeader eyebrow="Search performance" title="Keyword rankings" detail="See where Bridge Legal Services is showing up in local search." action={<Button variant="secondary"><CalendarDays className="h-4 w-4" /> Last 30 days</Button>} /><QueryState loading={q.isLoading} error={q.error}><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Keywords tracked" value="20 / 20" detail="All slots active" icon={Target} /><Metric label="Average position" value="8.6" detail="Across tracked terms" icon={BarChart3} accent="navy" /><Metric label="Improved" value="12" detail="Since last check" icon={ArrowUpRight} trend="up" /><Metric label="Declined" value="3" detail="Worth keeping an eye on" icon={ArrowDownRight} accent="rose" /></div><Card className="mt-5"><SectionTitle title="Ranking movement" detail="Daily positions across your highest-value terms" /><div className="h-40"><MiniChart values={[14, 13, 12, 12, 10, 9, 8.6]} color="#16243b" /></div></Card><Card className="mt-5"><div className="mb-5 flex flex-wrap gap-2"><Badge tone="navy">All keywords</Badge><Badge>Improving</Badge><Badge>Declining</Badge><Badge>Top 10</Badge><Badge>Top 20</Badge></div>{!rows.length ? <EmptyState title="No keyword data" detail="Your tracked keyword positions will appear after the first scan." icon={BarChart3} /> : <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-y border-slate-100 text-[10px] uppercase tracking-widest text-slate-400"><tr><th className="py-3">Keyword</th><th>Current</th><th>Previous</th><th>Change</th><th>Trend</th></tr></thead><tbody>{rows.map((r) => <tr key={r.id} className="border-b border-slate-100"><td className="py-4 font-semibold text-slate-800">{r.keyword}</td><td className="font-display font-bold">#{r.current}</td><td className="text-slate-500">#{r.previous}</td><td className={r.change > 0 ? 'font-semibold text-teal-600' : 'font-semibold text-rose-600'}>{r.change > 0 ? `↑ ${r.change}` : `↓ ${Math.abs(r.change)}`}</td><td className="h-10 w-32"><MiniChart values={r.trend} height={48} color={r.change > 0 ? '#20ad9f' : '#e05a5a'} /></td></tr>)}</tbody></table></div>}</Card></QueryState></>; }

function Competitors() { const q = useGetCompetitors({ query: { queryKey: getGetCompetitorsQueryKey() } }); const rows = q.data ?? []; return <><PageHeader eyebrow="Market context" title="Competitor overview" detail="Understand where other local firms are winning attention." action={<Button><Plus className="h-4 w-4" /> Add competitor</Button>} /><QueryState loading={q.isLoading} error={q.error}><Card><SectionTitle title="Search visibility comparison" detail="A practical view of your local market" /><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="border-y border-slate-100 text-[10px] uppercase tracking-widest text-slate-400"><tr><th className="py-3">Business</th><th>Reviews</th><th>Rating</th><th>Visibility</th><th>Keywords</th><th>Citations</th></tr></thead><tbody><tr className="border-b border-slate-100 bg-teal-50/50"><td className="py-4 font-bold text-slate-900">Bridge Legal Services <Badge tone="teal">You</Badge></td><td className="font-semibold">76</td><td>4.9</td><td className="font-display font-bold">87/100</td><td>12</td><td>46/50</td></tr>{rows.map((r) => <tr key={r.id} className="border-b border-slate-100"><td className="py-4 font-semibold text-slate-700">{r.name}</td><td>{r.reviews}</td><td>{r.rating.toFixed(1)}</td><td className="font-display font-bold">{r.visibility}/100</td><td>{r.keywords}</td><td>{r.citations}/50</td></tr>)}</tbody></table></div>{!rows.length && <EmptyState title="No competitors added" detail="Add local competitors to unlock the comparison view." icon={Users} />}</Card><Card className="mt-5 border-amber-200 bg-amber-50/50"><div className="flex gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-amber-200 text-amber-800"><Zap className="h-5 w-5" /></div><div><h2 className="font-display font-bold text-slate-900">Where competitors are winning</h2><p className="mt-1 max-w-2xl text-sm leading-6 text-slate-600">Competitor A has a larger review footprint, while your 4.9 rating remains stronger. The most efficient next move is to build review volume without sacrificing your response quality.</p><Button className="mt-4">View gap analysis <ChevronRight className="h-4 w-4" /></Button></div></div></Card></QueryState></>; }

function Content() { const q = useGetContentItems({ query: { queryKey: getGetContentItemsQueryKey() } }); const create = useCreateContentItem(); const qc = useQueryClient(); const [modal, setModal] = useState(false); const [title, setTitle] = useState(''); const [type, setType] = useState('Google Post'); const rows = q.data ?? []; return <><PageHeader eyebrow="Content planning" title="Content calendar" detail="Keep local content moving with a clear, shared plan." action={<Button onClick={() => setModal(true)}><Plus className="h-4 w-4" /> Add content idea</Button>} /><QueryState loading={q.isLoading} error={q.error}><Card><SectionTitle title="Upcoming content" detail="Ideas and posts connected to local search intent" /><div className="grid gap-3 md:grid-cols-2">{rows.map((r) => <div key={r.id} className="flex items-center gap-4 rounded-xl border border-slate-200 p-4"><div className="flex h-11 w-11 shrink-0 flex-col items-center justify-center rounded-lg bg-slate-100 text-slate-700"><span className="text-[10px] font-bold uppercase">{new Date(r.date).toLocaleDateString('en-CA', { month: 'short' })}</span><span className="font-display text-lg font-bold">{new Date(r.date).getDate()}</span></div><div className="min-w-0 flex-1"><h3 className="truncate text-sm font-bold text-slate-800">{r.title}</h3><p className="mt-1 text-xs text-slate-500">{r.type}</p></div><Badge tone={r.status === 'published' ? 'teal' : r.status === 'scheduled' ? 'amber' : 'slate'}>{r.status}</Badge></div>)}</div>{!rows.length && <EmptyState title="Your calendar is open" detail="Add a content idea to start planning your next local search win." icon={FileText} />}</Card><Card className="mt-5"><SectionTitle title="Content lanes" detail="A balanced mix keeps your profile useful" /><div className="grid gap-3 sm:grid-cols-4">{['Google Posts', 'FAQs', 'Service content', 'Blog ideas'].map((x, i) => <button key={x} onClick={() => setModal(true)} className="rounded-xl border border-slate-200 p-4 text-left hover:border-teal-300 hover:bg-teal-50/40"><div className="mb-3 flex h-8 w-8 items-center justify-center rounded-lg bg-teal-50 text-teal-700"><FileText className="h-4 w-4" /></div><p className="text-sm font-bold text-slate-800">{x}</p><p className="mt-1 text-xs text-slate-500">{[3, 5, 2, 4][i]} planned items</p></button>)}</div></Card></QueryState>{modal && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4"><form className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl" onSubmit={(e) => { e.preventDefault(); create.mutate({ data: { title, type, date: new Date().toISOString() } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetContentItemsQueryKey() }); setModal(false); setTitle(''); } }); }}><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-teal-700">New idea</p><h2 className="mt-1 font-display text-xl font-bold">Add content to calendar</h2></div><button type="button" onClick={() => setModal(false)}><X className="h-5 w-5 text-slate-400" /></button></div><label className="mt-5 block text-xs font-bold text-slate-600">Working title<input required value={title} onChange={(e) => setTitle(e.target.value)} className="mt-2 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-teal-500" placeholder="e.g. What to do after a speeding ticket" /></label><label className="mt-4 block text-xs font-bold text-slate-600">Content type<select value={type} onChange={(e) => setType(e.target.value)} className="mt-2 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm"><option>Google Post</option><option>FAQ</option><option>Service Content</option><option>Blog Idea</option></select></label><Button type="submit" disabled={create.isPending || !title.trim()} className="mt-5 w-full">{create.isPending ? 'Saving…' : 'Add to calendar'}</Button></form></div>}</>; }

function Recommendations() { const q = useGetRecommendations({ query: { queryKey: getGetRecommendationsQueryKey() } }); const ask = useAskRecommendation(); const [question, setQuestion] = useState(''); const [answer, setAnswer] = useState<any>(null); const rows = q.data ?? []; const submit = (value = question) => { if (!value.trim()) return; ask.mutate({ data: { question: value } }, { onSuccess: (data) => setAnswer(data) }); }; return <><PageHeader eyebrow="Advisor" title="AI local SEO assistant" detail="A clear second opinion on what to prioritize next." /><div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><Card><div className="mb-5 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-teal-50 text-teal-700"><Sparkles className="h-5 w-5" /></div><div><h2 className="font-display font-bold">Your biggest opportunities</h2><p className="text-xs text-slate-500">Prioritized from your account signals</p></div></div><div className="space-y-3">{rows.map((r) => <div key={r.id} className="rounded-xl border border-slate-200 p-4"><div className="flex items-center justify-between"><Badge tone={r.priority === 'high' ? 'rose' : 'amber'}>{r.priority} priority</Badge><span className="text-xs font-semibold text-teal-700">{r.impact}</span></div><h3 className="mt-3 text-sm font-bold">{r.title}</h3><p className="mt-1 text-sm leading-6 text-slate-500">{r.description}</p><div className="mt-3 flex items-start gap-2 rounded-lg bg-slate-50 p-3 text-xs"><CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-teal-600" /><span className="text-slate-600"><b>Recommended action:</b> {r.action}</span></div></div>)}{!rows.length && <EmptyState title="Recommendations are being prepared" detail="Your next set of opportunities will appear after the account scan." icon={Sparkles} />}</div></Card><Card className="h-fit border-slate-800 bg-[#16243b] text-white"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-teal-400 text-slate-900"><MessageSquare className="h-4 w-4" /></div><div><h2 className="font-display font-bold">Ask the assistant</h2><p className="text-xs text-slate-400">Demo answers use your workspace context</p></div></div><textarea value={question} onChange={(e) => setQuestion(e.target.value)} className="mt-5 min-h-[110px] w-full resize-none rounded-xl border border-white/10 bg-white/[0.07] p-3 text-sm text-white outline-none placeholder:text-slate-500 focus:border-teal-400" placeholder="Ask why your rankings changed…" /><Button disabled={ask.isPending || !question.trim()} onClick={() => submit()} className="mt-3 w-full bg-teal-400 text-slate-900 hover:bg-teal-300">{ask.isPending ? 'Thinking…' : 'Ask assistant'} <Send className="h-3.5 w-3.5" /></Button><div className="mt-5 flex flex-wrap gap-2">{['What should I fix first?', 'Why did visibility change?', 'Where am I losing visibility?'].map((x) => <button key={x} onClick={() => { setQuestion(x); submit(x); }} className="rounded-full border border-white/10 px-3 py-1.5 text-[11px] text-slate-300 hover:border-teal-400 hover:text-teal-300">{x}</button>)}</div>{answer && <div className="mt-5 rounded-xl bg-white p-4 text-sm text-slate-700"><p className="text-[10px] font-bold uppercase tracking-widest text-teal-700">Assistant answer</p><p className="mt-2 leading-6">{answer.answer}</p></div>}</Card></div></>; }

function Tasks() { const q = useGetTasks({ query: { queryKey: getGetTasksQueryKey() } }); const create = useCreateTask(); const update = useUpdateTask(); const qc = useQueryClient(); const [modal, setModal] = useState(false); const [title, setTitle] = useState(''); const [priority, setPriority] = useState<'high' | 'medium' | 'low'>('medium'); const tasks = q.data ?? []; const cycle = (task: Task) => { const next = task.status === 'todo' ? 'in_progress' : task.status === 'in_progress' ? 'completed' : 'todo'; update.mutate({ id: task.id, data: { status: next } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetTasksQueryKey() }) }); }; return <><PageHeader eyebrow="Action center" title="Issues & tasks" detail="A shared place for the small fixes that compound into better visibility." action={<Button onClick={() => setModal(true)}><Plus className="h-4 w-4" /> Add task</Button>} /><QueryState loading={q.isLoading} error={q.error}><div className="mb-5 grid gap-4 sm:grid-cols-3"><Metric label="Open tasks" value={`${tasks.filter((x) => x.status !== 'completed').length}`} detail="Need a decision or action" icon={ListChecks} /><Metric label="High priority" value={`${tasks.filter((x) => x.priority === 'high' && x.status !== 'completed').length}`} detail="Keep these moving" icon={AlertCircle} accent="rose" /><Metric label="Completed" value={`${tasks.filter((x) => x.status === 'completed').length}`} detail="This month" icon={CheckCircle2} accent="teal" /></div><Card><div className="mb-5 flex gap-2"><Badge tone="navy">All</Badge><Badge>High priority</Badge><Badge>In progress</Badge><Badge>Completed</Badge></div>{!tasks.length ? <EmptyState title="Your task list is clear" detail="Add an item when there is a local visibility action you want to track." icon={ListChecks} /> : <div className="space-y-2">{tasks.map((task) => <div key={task.id} className="flex flex-col gap-3 rounded-xl border border-slate-200 p-4 sm:flex-row sm:items-center"><button onClick={() => cycle(task)} className={cn('flex h-7 w-7 shrink-0 items-center justify-center rounded-full border-2', task.status === 'completed' ? 'border-teal-500 bg-teal-500 text-white' : 'border-slate-300 text-transparent hover:border-teal-500')}>{task.status === 'completed' && <Check className="h-4 w-4" />}</button><div className="min-w-0 flex-1"><p className={cn('text-sm font-bold', task.status === 'completed' && 'text-slate-400 line-through')}>{task.title}</p><p className="mt-1 text-xs text-slate-400">Due {fmtDate(task.dueDate)}</p></div><Badge tone={task.priority === 'high' ? 'rose' : task.priority === 'medium' ? 'amber' : 'slate'}>{task.priority}</Badge><Badge tone={task.status === 'completed' ? 'teal' : task.status === 'in_progress' ? 'amber' : 'slate'}>{task.status.replace('_', ' ')}</Badge></div>)}</div>}</Card></QueryState>{modal && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4"><form className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl" onSubmit={(e) => { e.preventDefault(); create.mutate({ data: { title, priority, dueDate: new Date(Date.now() + 7 * 86400000).toISOString() } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetTasksQueryKey() }); setModal(false); setTitle(''); } }); }}><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Add a task</h2><button type="button" onClick={() => setModal(false)}><X className="h-5 w-5 text-slate-400" /></button></div><input required value={title} onChange={(e) => setTitle(e.target.value)} placeholder="What needs to happen?" className="mt-5 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm" /><select value={priority} onChange={(e) => setPriority(e.target.value as typeof priority)} className="mt-3 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm"><option value="high">High priority</option><option value="medium">Medium priority</option><option value="low">Low priority</option></select><Button type="submit" disabled={create.isPending} className="mt-5 w-full">{create.isPending ? 'Creating…' : 'Create task'}</Button></form></div>}</>; }

function GoogleProfile() { return <><PageHeader eyebrow="Google presence" title="Google Business Profile" detail="A focused view of the profile customers see first." action={<Badge tone="teal"><Check className="mr-1 h-3 w-3" /> Connected</Badge>} /><div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Card><SectionTitle title="Business profile" detail="Bridge Legal Services" action={<Button variant="secondary"><Pencil className="h-3.5 w-3.5" /> Edit profile</Button>} /><div className="grid gap-4 sm:grid-cols-2">{[['Business name', 'Bridge Legal Services'], ['Category', 'Paralegal'], ['Location', 'Toronto, Ontario'], ['Phone', '(416) 555-0182'], ['Website', 'bridgelegalservices.ca'], ['Hours', 'Mon–Fri · 9:00 AM–6:00 PM']].map(([label, value]) => <div key={label} className="rounded-xl bg-slate-50 p-4"><p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{label}</p><p className="mt-2 text-sm font-semibold text-slate-800">{value}</p></div>)}</div></Card><Card><SectionTitle title="Profile health" detail="4 of 5 profile areas are strong" /><div className="flex items-center justify-center py-5"><div className="relative flex h-40 w-40 items-center justify-center rounded-full" style={{ background: 'conic-gradient(#20ad9f 0 92%, #e8edf2 92% 100%)' }}><div className="flex h-32 w-32 flex-col items-center justify-center rounded-full bg-white"><span className="font-display text-3xl font-bold">92%</span><span className="text-xs text-slate-400">healthy</span></div></div></div><Button variant="secondary" className="w-full">View full audit</Button></Card></div><Card className="mt-5"><SectionTitle title="Profile performance" detail="Last 30 days" /><div className="grid gap-3 sm:grid-cols-4">{[['Profile views', '1,248', '+16%', EyeIcon], ['Calls', '82', '+18%', PhoneIcon], ['Website clicks', '104', '+23%', Globe2], ['Direction requests', '67', '+11%', MapPin]].map(([label, value, change, Icon]: [string, string, string, typeof Activity]) => <div key={label} className="rounded-xl border border-slate-200 p-4"><Icon className="h-4 w-4 text-teal-600" /><p className="mt-4 text-xs text-slate-500">{label}</p><p className="mt-1 font-display text-2xl font-bold">{value}</p><p className="mt-1 text-xs font-semibold text-teal-700">{change}</p></div>)}</div></Card></>; }
function EyeIcon(props: { className?: string }) { return <Activity {...props} />; }
function PhoneIcon(props: { className?: string }) { return <Headphones {...props} />; }

function Reports() { return <><PageHeader eyebrow="Reporting" title="Monthly performance report" detail="August 2026 · A concise record of your local growth." action={<div className="flex gap-2"><Button variant="secondary"><Send className="h-4 w-4" /> Email report</Button><Button><FileText className="h-4 w-4" /> Download PDF</Button></div>} /><Card className="bg-[#16243b] text-white"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Badge tone="teal">August 2026</Badge><h2 className="mt-4 font-display text-2xl font-bold">The month in visibility</h2><p className="mt-2 max-w-lg text-sm leading-6 text-slate-400">Your profile is earning more attention, and the next gains are clear: keep review momentum while tightening citation accuracy.</p></div><div className="text-left md:text-right"><p className="text-xs uppercase tracking-widest text-slate-400">Visibility score</p><p className="mt-1 font-display text-5xl font-bold text-teal-300">87<span className="text-xl text-slate-500">/100</span></p><p className="mt-1 text-xs font-semibold text-teal-300">+6.4% vs last month</p></div></div></Card><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Reviews" value="+7" detail="New customer feedback" icon={Star} accent="amber" /><Metric label="Citations" value="46/50" detail="Listings healthy" icon={Globe2} /><Metric label="Keywords" value="+4" detail="Average improvement" icon={TrendingUp} trend="up" /><Metric label="Profile health" value="92%" detail="Complete and accurate" icon={ShieldCheck} accent="teal" /></div><Card className="mt-5"><SectionTitle title="Executive summary" detail="What changed and why it matters" /><div className="grid gap-5 md:grid-cols-3">{[['Visibility', 'Your local visibility score moved from 81 to 87, led by stronger keyword coverage.'], ['Reputation', 'Seven new reviews kept your 4.9 rating stable and improved customer confidence.'], ['Next focus', 'Resolve the BBB address mismatch and strengthen the stunt driving service page.']].map(([title, text]) => <div key={title} className="border-l-2 border-teal-400 pl-4"><h3 className="text-sm font-bold">{title}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{text}</p></div>)}</div></Card></>; }

function Billing() { const q = useGetBilling({ query: { queryKey: getGetBillingQueryKey() } }); const b = q.data; return <><PageHeader eyebrow="Account" title="Billing & plan" detail="A transparent view of what your monthly service includes." /><QueryState loading={q.isLoading} error={q.error}><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><Card className="border-slate-800 bg-[#16243b] text-white"><div className="flex items-start justify-between"><div><Badge tone="teal">Active plan</Badge><h2 className="mt-5 font-display text-2xl font-bold">{b?.plan ?? 'Local Pro'}</h2><p className="mt-2 text-sm text-slate-400">Your complete local visibility service</p></div><CreditCard className="h-6 w-6 text-teal-300" /></div><div className="mt-8 flex items-end gap-2"><span className="font-display text-4xl font-bold">${b?.price ?? 299}</span><span className="mb-1 text-sm text-slate-400">{b?.currency ?? 'CAD'} / month</span></div><div className="mt-6 border-t border-white/10 pt-5"><p className="text-xs text-slate-400">Next billing date</p><p className="mt-1 text-sm font-semibold">{b?.nextBilling ?? 'September 10, 2026'}</p></div><div className="mt-6 flex flex-wrap gap-2"><Button className="bg-teal-400 text-slate-900 hover:bg-teal-300">Manage subscription</Button><Button variant="ghost" className="text-slate-300 hover:bg-white/10 hover:text-white">Cancel plan</Button></div></Card><Card><SectionTitle title="Plan includes" detail="Everything working behind the scenes" /><div className="space-y-3">{(b?.included ?? ['50+ business listings', 'Google Profile monitoring', 'Review monitoring & outreach', '20 keyword tracking slots', 'Competitor monitoring', 'AI recommendations', 'Monthly reporting', 'Dedicated support']).map((x) => <div key={x} className="flex items-center gap-3 text-sm text-slate-700"><CheckCircle2 className="h-4 w-4 text-teal-600" />{x}</div>)}</div></Card></div></QueryState></>; }

function Settings() { const q = useGetSettings({ query: { queryKey: getGetSettingsQueryKey() } }); const update = useUpdateSettings(); const qc = useQueryClient(); const defaults: BusinessSettings = { businessName: 'Bridge Legal Services', phone: '(416) 555-0182', website: 'https://bridgelegalservices.ca', address: '240 Richmond St W, Toronto, ON', category: 'Traffic Ticket Defence / Paralegal', services: 'Traffic tickets, speeding tickets, careless driving, stunt driving', notifications: { newReview: true, rankingChanges: true, citationIssues: true, monthlyReport: true, competitorAlerts: false } }; const [form, setForm] = useState<BusinessSettings>(defaults); const [initialized, setInitialized] = useState(false); if (q.data && !initialized) { setForm(q.data); setInitialized(true); } const setField = (key: keyof BusinessSettings, value: string) => setForm((x) => ({ ...x, [key]: value })); const save = (e: React.FormEvent) => { e.preventDefault(); update.mutate({ data: form }, { onSuccess: (data) => { setForm(data); qc.setQueryData(getGetSettingsQueryKey(), data); } }); }; return <><PageHeader eyebrow="Workspace preferences" title="Settings" detail="Keep your business information and notification preferences current." /><form onSubmit={save}><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card><SectionTitle title="Business information" detail="This information powers your local listings." /><div className="grid gap-4 sm:grid-cols-2">{[['businessName', 'Business name'], ['phone', 'Phone'], ['website', 'Website'], ['address', 'Address'], ['category', 'Category'], ['services', 'Services']].map(([key, label]) => <label key={key} className="text-xs font-bold text-slate-600">{label}<input value={String(form[key as keyof BusinessSettings] ?? '')} onChange={(e) => setField(key as keyof BusinessSettings, e.target.value)} className="mt-2 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm font-normal text-slate-800 outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-100" /></label>)}</div></Card><Card><SectionTitle title="Notifications" detail="Choose what should reach your inbox." /><div className="space-y-4">{(Object.keys(form.notifications) as Array<keyof BusinessSettings['notifications']>).map((key) => <label key={key} className="flex cursor-pointer items-center justify-between gap-3"><span className="text-sm font-medium capitalize text-slate-700">{key.replace(/([A-Z])/g, ' $1')}</span><input type="checkbox" checked={form.notifications[key]} onChange={(e) => setForm((x) => ({ ...x, notifications: { ...x.notifications, [key]: e.target.checked } }))} className="h-4 w-4 accent-teal-600" /></label>)}</div></Card></div><div className="mt-5 flex justify-end"><Button type="submit" disabled={update.isPending}><Check className="h-4 w-4" />{update.isPending ? 'Saving changes…' : 'Save changes'}</Button></div></form></>; }

function Support() { const send = useCreateSupportRequest(); const [subject, setSubject] = useState(''); const [message, setMessage] = useState(''); const [sent, setSent] = useState(false); return <><PageHeader eyebrow="Client care" title="Help & support" detail="Your local visibility consultant is one message away." /><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Card className="bg-[#16243b] text-white"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-teal-400 text-slate-900"><Headphones className="h-5 w-5" /></div><h2 className="mt-5 font-display text-2xl font-bold">Dedicated support</h2><p className="mt-3 text-sm leading-6 text-slate-400">Tell us what you’re seeing and we’ll help translate it into the next useful action.</p><div className="mt-8 space-y-3"><button className="flex w-full items-center justify-between rounded-xl border border-white/10 p-3 text-left text-sm hover:bg-white/[0.06]">Book a call <ChevronRight className="h-4 w-4 text-teal-300" /></button><button className="flex w-full items-center justify-between rounded-xl border border-white/10 p-3 text-left text-sm hover:bg-white/[0.06]">Visit help center <ChevronRight className="h-4 w-4 text-teal-300" /></button></div></Card><Card><SectionTitle title="Send a message" detail="Most client requests receive a reply within one business day." />{sent ? <div className="rounded-xl bg-teal-50 p-6 text-center"><CheckCircle2 className="mx-auto h-8 w-8 text-teal-600" /><h3 className="mt-3 font-display font-bold">Message received</h3><p className="mt-1 text-sm text-slate-500">Your consultant will follow up shortly.</p><Button className="mt-5" onClick={() => setSent(false)}>Send another message</Button></div> : <form onSubmit={(e) => { e.preventDefault(); send.mutate({ data: { subject, message } }, { onSuccess: () => { setSent(true); setSubject(''); setMessage(''); } }); }}><label className="block text-xs font-bold text-slate-600">Subject<input required value={subject} onChange={(e) => setSubject(e.target.value)} className="mt-2 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm font-normal outline-none focus:border-teal-500" placeholder="What can we help with?" /></label><label className="mt-4 block text-xs font-bold text-slate-600">Message<textarea required value={message} onChange={(e) => setMessage(e.target.value)} rows={6} className="mt-2 w-full resize-none rounded-lg border border-slate-300 px-3 py-2.5 text-sm font-normal outline-none focus:border-teal-500" placeholder="Share a little context so we can help quickly." /></label><Button type="submit" disabled={send.isPending || !subject.trim() || !message.trim()} className="mt-4">{send.isPending ? 'Sending…' : 'Send request'} <Send className="h-4 w-4" /></Button></form>}</Card></div></>; }

function AppRoutes() { return <Shell><Switch><Route path="/" component={Overview} /><Route path="/listings" component={Listings} /><Route path="/reviews" component={Reviews} /><Route path="/google-profile" component={GoogleProfile} /><Route path="/rankings" component={Rankings} /><Route path="/competitors" component={Competitors} /><Route path="/content" component={Content} /><Route path="/recommendations" component={Recommendations} /><Route path="/tasks" component={Tasks} /><Route path="/reports" component={Reports} /><Route path="/billing" component={Billing} /><Route path="/settings" component={Settings} /><Route path="/support" component={Support} /><Route component={NotFound} /></Switch></Shell>; }
function App() { return <QueryClientProvider client={queryClient}><ErrorBoundary><AppRoutes /></ErrorBoundary></QueryClientProvider>; }
export default App;